import{_ as u,a0 as l,w as p,s,ao as r,I as a,x as i,a1 as n,A as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const b=JSON.parse('{"title":"Authenticator：一个 Linux 上的 Authy 的简单的开源替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Authenticator：一个 Linux 上的 Authy 的简单的开源替代品 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Authenticator：一个 Linux 上的 Authy 的简单的开源替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Authenticator：一个 Linux 上的 Authy 的简单的开源替代品 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux","title":"Authenticator：一个 Linux 上的 Authy 的简单的开源替代品","tag":"202212","desc":""},"relativePath":"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux.md","filePath":"[post].md"}'),h={name:"202212/20221117.1 ⭐️ Authenticator A Simple Open-Source App to Replace Authy on Linux.md"};function d(m,t,A,f,x,g){const e=l("Link");return p(),s("div",null,[t[21]||(t[21]=r('<h1 id="authenticator-一个-linux-上的-authy-的简单的开源替代品" tabindex="-1">Authenticator：一个 Linux 上的 Authy 的简单的开源替代品 <a class="header-anchor" href="#authenticator-一个-linux-上的-authy-的简单的开源替代品" aria-label="Permalink to “Authenticator：一个 Linux 上的 Authy 的简单的开源替代品”">​</a></h1><p>Authy 是一款流行的应用，用于存储和管理双因素代码。它是一项基于云的服务，可为你提供便利的工业级安全性。不幸的是，它不是开源的。</p><p>你会考虑在 Linux 桌面上使用更直接（和开源）的身份验证器应用吗？</p><p>嗯，当然，你不能使用云同步。但是你可以为双因素身份验证码做个备份。记住这点，让我告诉你更多有关 Authenticator 的信息。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-app-ft.png" alt="authenticator app ft"></p><h3 id="authenticator-生成双因素身份验证代码" tabindex="-1">Authenticator：生成双因素身份验证代码 <a class="header-anchor" href="#authenticator-生成双因素身份验证代码" aria-label="Permalink to “Authenticator：生成双因素身份验证代码”">​</a></h3><p>当你启用在线服务的双因素身份验证时，大多数服务都会为你提供令牌/QR 码，你可以添加/扫描以生成代码。</p><p>Authenticator 就是这样一款适用于 Linux 的应用，他可让你添加双因素身份验证码。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-ui.png" alt="authenticator ui"></p><p>它是一个自由开源的应用，具有添加各种支持双因素身份验证的令牌和网站的基本功能。</p><h3 id="身份验证器的特点" tabindex="-1">身份验证器的特点 <a class="header-anchor" href="#身份验证器的特点" aria-label="Permalink to “身份验证器的特点”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-auto-lock.png" alt="authenticator 自动锁定"></p><p>你获得的一些基本功能包括：</p><ul><li>使用相机或截图的二维码扫描器</li><li>使用密码保护应用</li><li>自动锁定应用</li><li>支持各种算法（SHA-1/SHA-256/SHA-512）</li><li>支持基于时间/基于计数器/流式计算方法</li><li>备份/恢复选项（FreeOTP、Aegis 和 OTP、Bitwarden 和 Google Authenticator）</li></ul><p>你可以设置自定义选项，并能够根据服务提供的支持添加自定义的提供者。可以为提供者添加自定义图标，以帮助你区分身份验证代码。</p><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-custom-provider.png" alt="authenticator 自定义提供程序"></p><p>在大多数情况下，默认设置应该适用于网站。但是，如果它不起作用，你可能需要与提供者核实确切的详细信息。</p><p>该应用还具有开箱即用的多个提供者，例如 Google Drive 和 Proton Mail。因此，你无需为添加的每个条目添加自定义配置。</p><h3 id="在-linux-上安装-authenticator" tabindex="-1">在 Linux 上安装 Authenticator <a class="header-anchor" href="#在-linux-上安装-authenticator" aria-label="Permalink to “在 Linux 上安装 Authenticator”">​</a></h3><p><img src="https://itsfoss.com/wp-content/uploads/2022/11/authenticator-add-new-code.png" alt="authenticator 添加新代码"></p><p>Authenticator 以 Flatpak 的形式提供。因此，你可以将它安装在任何 Linux 发行版上。</p><p>只需输入以下命令即可安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>flatpak install flathub com.belmoussaoui.Authenticator</span></span></code></pre></div>',23)),a("p",null,[t[1]||(t[1]=i("你可以前往其 ",-1)),n(e,{href:"https://flathub.org/apps/details/com.belmoussaoui.Authenticator"},{default:o(()=>[...t[0]||(t[0]=[i("Flathub",-1)])]),_:1}),t[2]||(t[2]=i(" 或 GitLab 页面探索更多信息。",-1))]),a("p",null,[t[4]||(t[4]=i("如果你是 Linux 世界的新手，请参阅我们的 ",-1)),n(e,{href:"https://itsfoss.com/flatpak-guide/"},{default:o(()=>[...t[3]||(t[3]=[i("Flatpak 指南",-1)])]),_:1}),t[5]||(t[5]=i(" 进行设置。你的软件中心可能已经启用了 Flatpak 集成。这种情况下，你可以搜索安装它。",-1))]),t[22]||(t[22]=a("h3",{id:"使用开源身份验证器应用确保安全性和可靠性",tabindex:"-1"},[i("使用开源身份验证器应用确保安全性和可靠性 "),a("a",{class:"header-anchor",href:"#使用开源身份验证器应用确保安全性和可靠性","aria-label":"Permalink to “使用开源身份验证器应用确保安全性和可靠性”"},"​")],-1)),t[23]||(t[23]=a("p",null,"我们经常依赖云驱动的工具来处理所有事情。当然，这很方便。",-1)),t[24]||(t[24]=a("p",null,"但是，有时桌面应用更有用。如果你也这么想并考虑进行转换，Authenticator 可能是一款值得安装的出色的应用，可以用于双因素身份验证码。",-1)),t[25]||(t[25]=a("hr",null,null,-1)),a("p",null,[t[7]||(t[7]=i("via: ",-1)),n(e,{href:"https://itsfoss.com/authenticator/"},{default:o(()=>[...t[6]||(t[6]=[i("https://itsfoss.com/authenticator/",-1)])]),_:1})]),a("p",null,[t[12]||(t[12]=i("作者：",-1)),n(e,{href:"https://itsfoss.com/author/ankush/"},{default:o(()=>[...t[8]||(t[8]=[i("Ankush Das",-1)])]),_:1}),t[13]||(t[13]=i(" 选题：",-1)),n(e,{href:"https://github.com/lkxed"},{default:o(()=>[...t[9]||(t[9]=[i("lkxed",-1)])]),_:1}),t[14]||(t[14]=i(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:o(()=>[...t[10]||(t[10]=[i("geekpi",-1)])]),_:1}),t[15]||(t[15]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:o(()=>[...t[11]||(t[11]=[i("wxy",-1)])]),_:1})]),a("p",null,[t[18]||(t[18]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[16]||(t[16]=[i("LCTT",-1)])]),_:1}),t[19]||(t[19]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:o(()=>[...t[17]||(t[17]=[i("Linux中国",-1)])]),_:1}),t[20]||(t[20]=i(" 荣誉推出",-1))])])}const T=u(h,[["render",d]]);export{b as __pageData,T as default};
